</ul>

<h2>منابع و راستی‌آزمایی</h2>
<p>اطلاعات این مقاله بر پایه صفحه آبشار ازنادر در کویرها و بیابان‌های ایران، صفحه دورود در صدا و سیمای لرستان، گزارش تصویری مشرق نیوز، مطلب کجارو، آخرین خبر، لحظه آخر، یوتوپین و ویکی‌پدیای فارسی نوشته شده است. فاصله‌ها، ساعت روشنایی و وضعیت آب در طول فصل تغییر می‌کند؛ پیش از حرکت، اطلاعات روز را از اهالی دره اسپر یا منابع محلی بگیرید.</p>
