<p>داخل تنگه، آب زلال و خنک در حوضچه‌هایی می‌ایستد که عمق بعضی از آن‌ها در فصل‌های پرآب به حدود دو متر می‌رسد؛ همین ویژگی، لی لی را در تابستان به یکی از محبوب‌ترین مقصدهای آبتنی و قایق‌سواری طبیعت‌گردان لرستان تبدیل کرده است. اما لی لی فقط یک تفریحگاه آبی نیست: کتیبه‌ای یونانی با حدود دو هزار سال قدمت روی صخره‌ای آهکی مسطح مشرف به تنگه حک شده که این دره را به یک مقصد تاریخی هم تبدیل می‌کند.</p>
