<h2>چرا تنگه لی لی نمای برتر دورود است؟</h2>
<ul>
<li><strong>دره‌ای صخره‌ای با فرسایش طبیعی منحصربه‌فرد:</strong> تنگه در اثر جریان مداوم آب و وزش باد در طول هزاران سال شکل گرفته؛ فرسایش صخره‌ها سطوح صیقلی و دیواره‌هایی با اشکال چشمگیر پدید آورده که لی لی را از سایر تنگه‌های منطقه متمایز می‌کند.</li>
<li><strong>حوضچه‌های طبیعی با امکان شنا و قایق‌سواری:</strong> رود ماربره در مسیر عبور از تنگه، استخرها و حوضچه‌های متعددی ساخته است؛ در فصل‌های پرآب عمق برخی از آن‌ها به حدود دو متر می‌رسد و امکان آبتنی و قایق‌سواری فراهم است.</li>
<li><strong>پیشینه تاریخی با کتیبه یونانی:</strong> یک کتیبه یونانی به خط و زبان یونان باستان در این تنگه شناسایی شده که قدمت آن به حدود ۱۰۰ پیش از میلاد تا ۱۰۰ میلادی بازمی‌گردد؛ سطح کتیبه روی یک صخره آهکی مسطح و در ارتفاع حدود ۱۶۰۳ متری حک شده است.</li>
<li><strong>تنوع پوشش گیاهی و جانوری:</strong> درختان بلوط، بادام کوهی و زالزالک همراه گیاهان دارویی مانند آویشن، گل گاوزبان و نعنا؛ حیات وحش منطقه هم شامل بز کوهی، میش، روباه و خزندگانی مانند مار می‌شود.</li>
<li><strong>دسترسی خودرویی تا نزدیکی ورودی:</strong> برخلاف بسیاری از جاذبه‌های طبیعی منطقه، می‌توان با خودرو تا نزدیکی ورودی تنگه رفت و باقی مسیر را با پیاده‌روی متوسط (حدود ۴۵ دقیقه از چمنار) طی کرد.</li>
</ul>

<h2>تنگه لی لی کجاست؟</h2>
<p>تنگه لی لی در <a href="/province/lorestan/">استان لرستان</a>، <a href="/city/dorud/">شهرستان دورود</a> و حدود ۲۰ کیلومتری شرق این شهرستان، در مجاورت روستای چمنار از توابع بخش مرکزی و دهستان حشمت‌آباد و نرسیده به روستای سیره (لاسوره) قرار دارد. مختصات تقریبی آن در منابع محلی N۳۳ ۲۶ E۴۹ ۱۲ گزارش شده و پروژه کاتالوگ کتیبه‌های یونانی ایران برای محل کتیبه، مختصات ۳۳٫۴۲۲۶ و ۴۹٫۱۷۱۷ را ثبت کرده است. تنگه در غرب <a href="/attraction/gahar-lake-dorud/">دریاچه گهر</a> و قله اشترانکوه قرار می‌گیرد و رود ماربره پس از عبور از آن، به سمت شمال و شهر دورود می‌رود و در نهایت به رود سزار می‌پیوندد.</p>
<p>درباره نام: «لی لی» نامی است که اهالی محل به این تنگه داده‌اند؛ در منطقه درختان گیلاس وجود دارد و محلی‌ها به گیلاس‌های ریز «لی لی» می‌گویند. نام «سورپیلو» هم از پلی به همین نام در نزدیکی تنگه گرفته شده است. در متن منابع، نام روستای نزدیک به تنگه به شکل‌های چمنار (چمنار)، سیره/لاسوره و سیرم ثبت شده است؛ اگر با راهنمای محلی حرکت کنید، این نام‌ها در مسیر برایتان روشن می‌شود.</p>

<h2>مسیر دسترسی؛ از دورود تا ورودی تنگه</h2>
<p>وضعیت جاده‌های فرعی و مسیرهای پیاده‌روی بسته به بارش‌های فصلی و شرایط محلی تغییر می‌کند؛ پرس‌وجو از اهالی روستای چمنار پیش از حرکت توصیه می‌شود.</p>
<h3>۱) با خودرو از دورود (مسیر اصلی)</h3>
<p>از شهر دورود وارد جاده قدیم ازنا–دورود شوید. پس از رسیدن به دو راهی، به سمت راست بپیچید و مسیر را تا روستای چمنار ادامه دهید. فاصله دورود تا چمنار حدود ۱۴ کیلومتر است و حدود ۲۰ دقیقه رانندگی زمان می‌برد. از چمنار تا ورودی تنگه حدود ۴۵ دقیقه پیاده‌روی لازم است. دسترسی با خودرو تا نزدیکی ورودی تنگه هم امکان‌پذیر است.</p>
<h3>۲) از خرم‌آباد و شهرهای همسایه</h3>
<p>از <a href="/city/khorramabad/">خرم‌آباد</a> به سمت <a href="/city/borujerd/">بروجرد</a> و سپس دورود حرکت کنید؛ فاصله خرم‌آباد تا تنگه لی لی حدود ۱۰۰ کیلومتر و حدود دو ساعت است.</p>
<h3>۳) از تهران</h3>
<p>مسیر تهران – سلفچگان – اراک – بروجرد – دورود – تنگه لی لی حدود ۶۰۰ کیلومتر و حدود ۸ ساعت زمان می‌برد. مسیر جایگزین از ساوه – همدان – ملایر – بروجرد هم حدود ۶۵۰ کیلومتر است.</p>
<h3>۴) با قطار و اتوبوس</h3>
<p>نزدیک‌ترین ایستگاه راه‌آهن، ایستگاه دورود است؛ از آنجا با تاکسی یا وسایل حمل‌ونقل محلی به سمت روستای چمنار بروید. از شهرهای بزرگ ایران هم اتوبوس‌هایی به خرم‌آباد و دورود رفت‌وآمد می‌کنند و ادامه مسیر با تاکسی یا اتوبوس‌های محلی انجام می‌شود.</p>

<h2>بهترین زمان بازدید</h2>
<ul>
<li><strong>بهار (فروردین تا خرداد):</strong> تنگه پرآب‌ترین حالت خود را دارد و طبیعت اطراف سرسبز و پوشیده از گل‌های وحشی است. رود ماربره در این فصل جریان پرحجمی دارد؛ اما همین پرآبی برای شناگران غیرماهر خطرساز است.</li>
<li><strong>تابستان (تیر تا شهریور):</strong> هوای منطقه گرم‌تر است، اما آب حوضچه‌ها خنک و برای آبتنی و شنا مطلوب است؛ این فصل برای شنا و قایق‌سواری مناسب‌تر است.</li>
<li><strong>پاییز (مهر تا آبان):</strong> تا اوایل پاییز امکان بازدید وجود دارد و مناظر پاییزی منطقه دیدنی است؛ لباس گرم همراه ببرید.</li>
<li><strong>زمستان:</strong> به دلیل کوهستانی بودن منطقه و سردسیر بودن دورود، سفر به تنگه در زمستان توصیه نمی‌شود.</li>
</ul>
