<!-- تصویر داخل مقاله ۲: نمای پاییزی تنگه برای نمایش تغییرات فصلی — alt: «تنگه لی لی دورود در فصل پاییز با دیواره‌های صخره‌ای» -->

<h2>حوضچه‌های طبیعی، شنا و قایق‌سواری</h2>
<p>حوضچه‌ها ستون فقرات تفریحی تنگه لی لی هستند. رود ماربره در مسیر خود، آب را در فرورفتگی‌های صخره‌ای جمع می‌کند و استخرهایی طبیعی می‌سازد که آب آن‌ها در تابستان خنک و شفاف است. عمق بعضی از این حوضچه‌ها در فصل‌های پرآب به حدود دو متر می‌رسد و قایق‌سواری یکی از فعالیت‌های اصلی همین بخش از تنگه است.</p>
<p>سه نکته را جدی بگیرید: اول اینکه به مهارت شنا نیاز دارید و برای کودکانی که شنا بلد نیستند جای امنی وجود ندارد. دوم اینکه پرآبی بهار جریان آب را قوی می‌کند و ورود به آب در آن شرایط برای غیرحرفه‌ای‌ها خطرناک است. سوم اینکه کف و دیواره حوضچه‌ها لغزنده‌اند؛ کفش مناسب و احتیاط روی سنگ خیس، ساده‌ترین بیمه سفر شما است. برای قایق‌سواری هم حتماً از اهالی و راهنمای محلی درباره وضعیت روز و عمق آب بپرسید.</p>

<h2>کتیبه یونانی؛ دو هزار سال تاریخ در دل تنگه</h2>
<p>لی لی یک تنگه معمولی نیست: کتیبه‌ای یونانی روی صخره‌ای آهکی مسطح مشرف به تنگه شناسایی شده که در کاتالوگ پروژه «ایرانوهلنیکا» (بنیاد پژوهش‌های تاریخی آتن، ذیل پروژه نقشه‌برداری برخوردهای فرهنگی یونان و ایران) ثبت شده است. قدمت این کتیبه در بازه حدود ۱۰۰ پیش از میلاد تا ۱۰۰ میلادی تخمین زده می‌شود؛ همین بازه در مقاله علمی منتشرشده در مجله ZPE (شماره ۲۲۸، سال ۲۰۲۳) برای این سنگ‌نوشته گزارش شده است. سطح کتیبه روی صخره‌ای آهکی مسطح و بر پایه گزارش‌های محلی در ارتفاع حدود ۱۶۰۳ متری قرار دارد و ابعاد سطح نوشته‌شده در کاتالوگ حدود ۰٫۴۳ متر ارتفاع و ۰٫۶۳ تا ۰٫۶۹ متر طول ثبت شده است.</p>
<p>اهمیت این کتیبه در دوری آن از شهرها و مسیرهای باستانی اصلی است؛ این سنگ‌نوشته در دل کوهستان زاگرس و در دل همان تنگه‌ای حک شده که امروز مقصد طبیعت‌گردی است. اگر در تنگه با چنین آثاری روبه‌رو شدید، از تماس فیزیکی، مالیدن، تراشیدن یا انداختن زباله در پای آن خودداری کنید و هر اثر تخریبی را به منابع محلی و میراث فرهنگی اطلاع دهید.</p>

<h2>گیاهان و حیات وحش</h2>
<p>پوشش گیاهی اطراف تنگه ترکیبی از جنگل و مرتع است: بلوط، بادام کوهی، زالزالک و گیاهان دارویی و معطر مانند آویشن، گل گاوزبان و نعنا در دامنه‌ها و حاشیه رود می‌روید. همین پوشش گیاهی، زیست‌بومی برای حیات وحش ساخته است: بز کوهی، میش، روباه و خزندگانی مانند مار در منطقه دیده یا گزارش شده‌اند. در تابستان حشرات و پشه‌ها فعال‌تر هستند و گیاهان دارویی نباید بدون رعایت قاعده برداشت شوند؛ برداشت بی‌رویه، همان پوششی را از بین می‌برد که زیبایی و سایه تنگه به آن بسته است.</p>
<p>فاصله با حیات وحش قاعده ساده‌ای دارد: نزدیک نشوید، غذا ندهید و مسیر عبور جانوران را نبندید. مارها هم بخشی از منطقه‌اند؛ روی سنگ‌های گرم استراحت می‌کنند و پیش از نشستن یا برداشتن وسایل، اطراف را یک بار نگاه کنید.</p>

<h2>مناسب چه کسانی است؟</h2>
<ul>
<li><strong>طبیعت‌گردان و عکاسان:</strong> صخره‌های بلند، حوضچه‌های زلال و پوشش گیاهی متنوع، فرصت‌های عکاسی گسترده‌ای فراهم می‌کند.</li>
<li><strong>علاقه‌مندان به تفریحات آبی:</strong> شنا در حوضچه‌های طبیعی و قایق‌سواری در مسیر رودخانه، فعالیت اصلی تنگه است.</li>
<li><strong>طبیعت‌گردان با آمادگی متوسط:</strong> پیاده‌روی حدود ۴۵ دقیقه‌ای از روستای چمنار برای این گروه قابل انجام است.</li>
<li><strong>علاقه‌مندان تاریخ و باستان‌شناسی:</strong> کتیبه یونانی تنگه، این مسیر را برایشان به یک مقصد مستند تبدیل می‌کند.</li>
</ul>
<p><strong>نامناسب برای:</strong> سالمندان، خانواده‌های دارای کودکان خردسال و افرادی که آمادگی جسمانی ندارند. مسیر پیاده‌روی در بخش‌هایی نیازمند عبور از صخره‌ها و آشنایی با اصول اولیه کوهنوردی است.</p>

<h2>نکات ایمنی و محیط‌زیستی</h2>
<ul>
<li><strong>عبور از صخره‌ها با احتیاط:</strong> داخل تنگه صخره‌هایی وجود دارد که عبور از آن‌ها آشنایی با اصول اولیه کوهنوردی و تجهیزات ساده می‌خواهد.</li>
<li><strong>احتیاط در شنا:</strong> عمق حوضچه‌ها در فصل‌های پرآب گاهی به دو متر می‌رسد؛ خطر غرق‌شدن، به‌ویژه در حوضچه‌های عمیق، واقعی است.</li>
<li><strong>کفش مناسب:</strong> مسیر کوهستانی و سنگ‌های خیس لغزنده‌اند؛ کفش کوهنوردی چنگ‌دار بپوشید.</li>
<li><strong>آب و خوراکی همراه ببرید:</strong> نزدیک تنگه امکاناتی برای تهیه غذا و آب نیست.</li>
<li><strong>بررسی شرایط جوی:</strong> با بارش باران، سطح صخره‌ها لغزنده و خطرناک می‌شود؛ وضعیت هوا را پیش از حرکت بررسی کنید.</li>
<li><strong>فاصله با حیات وحش:</strong> منطقه زیستگاه بز کوهی، میش، روباه و مار است؛ فاصله خود را حفظ کنید.</li>
<li><strong>زباله را با خود ببرید:</strong> منطقه فاقد سیستم جمع‌آوری زباله است؛ هرچه آورده‌اید بازگردانید.</li>
<li><strong>رعایت حریم کتیبه تاریخی:</strong> در صورت مشاهده کتیبه یونانی، از تماس فیزیکی با آن خودداری کنید و به آن آسیب نزنید.</li>
<li><strong>آنتن و زمان برگشت:</strong> در دره آنتن‌دهی کامل نیست؛ زمان بازگشت را با همراهان هماهنگ کنید و پیش از تاریکی از تنگه بیرون بیایید.</li>
</ul>

<h2>برنامه پیشنهادی بازدید و اقامت</h2>
<ol>
<li>صبح زود از دورود حرکت کنید؛ حدود ۲۰ دقیقه رانندگی تا روستای چمنار.</li>
<li>خودرو را در جای مطمئن روستا یا نزدیکی ورودی پارک کنید و از اهالی وضعیت مسیر و آب را بپرسید.</li>
<li>حدود ۴۵ دقیقه پیاده‌روی تا ورودی تنگه؛ در مسیر از قاب‌های پانوراما و پوشش گیاهی عکاسی کنید.</li>
<li>دو تا سه ساعت در تنگه: گشت بین حوضچه‌ها، عکاسی، آبتنی یا قایق‌سواری با رعایت نکات ایمنی.</li>
<li>برای ناهار به روستا برگردید؛ در نزدیکی تنگه اقامتگاه بوم‌گردی و سوپرمارکت وجود دارد و اقامت شبانه در فصل بهار و تابستان گزینه خوبی است.</li>
<li>اگر روز دوم دارید، مسیر را با <a href="/attraction/aznadar-waterfall-doroud/">آبشار ازنادر</a> یا <a href="/attraction/babahur-forest-park-dorud/">پارک جنگلی باباهور</a> کامل کنید.</li>
</ol>

